window.CourseSearchIndex=[{"title": "ECE 6390 · Satellite Communications and Navigation Systems", "course": "gt/ece6390", "code": "ECE 6390", "group": "Course overview", "route": "/courses/gt/ece6390/", "text": "Orbits, spacecraft systems, radio links, antennas, navigation, and digital communications.", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Kepler ellipse", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/kepler-ellipse/", "text": "An ellipse sweeps equal areas in equal times", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "GEO & rotating Earth", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/geo-frames/", "text": "A stationary point in the sky is moving in space", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Elevation & horizon", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/look-triangle/", "text": "Elevation is an angle at the station, not Earth’s center", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Azimuth quadrants", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/azimuth-components/", "text": "East and north components determine the bearing", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Solar push", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/solar-pressure-components/", "text": "Project one sunlight push onto rotating orbital axes", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Integration drift", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/numerical-orbits/", "text": "The same physics can produce different numerical drift", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Two-burn transfer", "course": "gt/ece6390", "code": "ECE 6390", "group": "Orbits", "route": "/courses/gt/ece6390/topics/hohmann-transfer/", "text": "One burn raises apogee; the next circularizes", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Eclipse & battery", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/eclipse-battery/", "text": "One eclipse is an energy bill; every orbit must repay it", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Solar array", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/solar-array/", "text": "Sun-facing area and cell performance set useful power", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Rocket equation", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/rocket-mass/", "text": "A later burn’s fuel must ride through every earlier burn", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Electric thrust", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/electric-propulsion/", "text": "High exhaust speed saves propellant but costs thrust at fixed power", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Heat & radiator", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/thermal-balance/", "text": "RF power, waste heat and radiator temperature are connected", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Radiation & voting", "course": "gt/ece6390", "code": "ECE 6390", "group": "Systems", "route": "/courses/gt/ece6390/topics/radiation-redundancy/", "text": "Three copies mask one bad bit; shared failures can defeat the vote", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Divergence & curl", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/divergence-curl/", "text": "Outward flow and local circulation measure different things", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Double curl pinwheels", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/double-curl/", "text": "Pinwheels measure the swirl of the axle field", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Displacement current", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/displacement-current/", "text": "A charging capacitor keeps magnetic circulation continuous", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Helmholtz curvature", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/helmholtz-curvature/", "text": "The wave equation ties spatial curvature to the field", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "E, H & energy", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/plane-wave/", "text": "A plane wave carries perpendicular fields together", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Standing waves", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/standing-wave/", "text": "Counter-propagating waves can leave fixed nodes", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Polarization", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/polarization/", "text": "Watch the electric-field tip trace its polarization", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Interference & phasors", "course": "gt/ece6390", "code": "ECE 6390", "group": "Waves", "route": "/courses/gt/ece6390/topics/phasor-interference/", "text": "Add fields before squaring to find power", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "dB & distance", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/db-distance/", "text": "Logarithms turn power ratios into distances you can compare", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Link budget", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/link-budget/", "text": "Follow carrier power to the receiver, then compare it with noise", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Noise cascade", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/receiver-noise/", "text": "A lossy first stage makes later low-noise gain less useful", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Doppler", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/doppler-shift/", "text": "Only the line-of-sight velocity changes range instantaneously", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Rain & elevation", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/rain-path/", "text": "A low look angle takes a longer path through the rain", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Bandwidth & noise", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/bandwidth-noise/", "text": "More bandwidth admits more noise but may carry more information", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Spreading and capture", "course": "gt/ece6390", "code": "ECE 6390", "group": "RF", "route": "/courses/gt/ece6390/topics/free-space-flux/", "text": "A receiver captures a small part of an expanding power flow", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Dipole patterns", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/dipole-pattern/", "text": "A doughnut-shaped beam has an axial null", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Aperture addition", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/aperture-phasors/", "text": "A pattern comes from adding fields with phase", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Circular aperture", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/circular-aperture/", "text": "A circular opening produces a Bessel beam", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Dish and pointing", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/dish-gain/", "text": "A larger dish collects more power and needs better pointing", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Usable band", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/reflector-screens/", "text": "Electrical size, surface precision, and range set different screens", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Arrays", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/array-multiplication/", "text": "The array factor multiplies the element pattern", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Path + feed phase", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/array-path-phase/", "text": "Why broadside adds while another direction cancels", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Planar steering", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/planar-array/", "text": "A plane of elements controls two directional coordinates", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Beam to footprint", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/array-footprint/", "text": "An angular beam becomes a patch of ground through geometry", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Analog and digital combining", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/beamforming-frontends/", "text": "The location of beamforming changes which hardware sees interference", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Gain and matching", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/gain-references/", "text": "Accepted, radiated, and incident power use different references", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Pattern to absolute gain", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/array-normalization/", "text": "A relative pattern becomes directivity only after angular integration", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Solid angle and power", "course": "gt/ece6390", "code": "ECE 6390", "group": "Antennas", "route": "/courses/gt/ece6390/topics/solid-angle/", "text": "Equal angular rectangles cover different areas on a sphere", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Sampling & aliasing", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/sampling-alias/", "text": "Different continuous waves can give exactly the same samples", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Quantization & PCM", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/quantization-pcm/", "text": "Sampling fixes when; quantization fixes which amplitude level", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Compression vs coding", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/source-compression/", "text": "Compression removes redundancy; error correction deliberately adds it", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Pulses & ISI", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/nyquist-pulse/", "text": "A pulse can overlap its neighbors while giving zero interference at the right sampling instants", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Pulse width and spectrum", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/rectangular-pulse-spectrum/", "text": "A short rectangular pulse spreads across a wide range of frequencies", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Matched filter and timing", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/matched-filter/", "text": "A time-reversed pulse collects a known waveform into a decision sample", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Multipath and OFDM", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/ofdm-multipath/", "text": "A delayed echo makes channel gain vary across frequency", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "The modem signal chain", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/modem-chain/", "text": "Rates and waveform choices belong to specific stages of the modem", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "I/Q & decisions", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/iq-constellation/", "text": "A modulation symbol chooses one point in the I/Q plane", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Bits, baud & bandwidth", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/rate-bandwidth/", "text": "Keep information bits, coded bits and modulation symbols separate", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Adaptive MODCOD", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/adaptive-modcod/", "text": "Use a robust mode in a fade and a faster mode when margin returns", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Amplifier & backoff", "course": "gt/ece6390", "code": "ECE 6390", "group": "Digital", "route": "/courses/gt/ece6390/topics/amplifier-backoff/", "text": "Constellation geometry changes what a nonlinear amplifier distorts", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "GPS orbit geometry", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-orbits/", "text": "Inclined MEO planes spread satellites across the sky", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Doppler pass", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/doppler-pass/", "text": "A nearer pass changes its range rate more sharply", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Range & clock", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/pseudorange-clock/", "text": "One clock offset adds the same distance error to every pseudorange", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Earth-fixed coordinates", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/navigation-frames/", "text": "Earth-fixed coordinates turn latitude and longitude into Cartesian positions", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Geometry & precision", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-geometry/", "text": "Similar range errors can produce very different position uncertainty", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Three-dimensional DOP", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-dop-3d/", "text": "Six sky directions constrain east, north, up and receiver clock together", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Range-error budget", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-error-budget/", "text": "Independent range uncertainties add through their variances", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Code correlation", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/pn-correlation/", "text": "A delayed code is found by testing many alignments", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Shift register and PN code", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/lfsr-code/", "text": "A short binary recurrence creates a long recognizable chip sequence", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Spreading and processing gain", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/processing-gain/", "text": "A known fast code lets the receiver collect a slow data bit coherently", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "CDMA near–far effect", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/near-far/", "text": "A strong unwanted code can overwhelm a weaker desired correlation", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Code-delay and Doppler search", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/gnss-acquisition/", "text": "A receiver searches code alignment and carrier frequency together", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Dual-frequency ranging", "course": "gt/ece6390", "code": "ECE 6390", "group": "Navigation", "route": "/courses/gt/ece6390/topics/dual-frequency/", "text": "Two frequencies separate the leading ionospheric delay from common range", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "GeorgiaTenna project", "course": "gt/ece6390", "code": "ECE 6390", "group": "Interactive tools", "route": "/courses/gt/ece6390/project/", "text": "Aperture, feeds, phases, steering, normalization, link budget and geographic coverage", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Orbit and Sun", "course": "gt/ece6390", "code": "ECE 6390", "group": "Interactive tools", "route": "/courses/gt/ece6390/orbit/", "text": "Orbital forces, look angles and Sun geometry", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "Solar acceleration components", "course": "gt/ece6390", "code": "ECE 6390", "group": "Interactive tools", "route": "/courses/gt/ece6390/solar/", "text": "Radial and tangential projections of solar pressure", "courseTitle": "Satellite Communications and Navigation Systems", "institution": "Georgia Tech"}, {"title": "ECE 6612 · Computer Network Security", "course": "gt/ece6612", "code": "ECE 6612", "group": "Course overview", "route": "/courses/gt/ece6612/", "text": "Network security foundations, beginning with authenticated encryption and secure session establishment.", "courseTitle": "Computer Network Security", "institution": "Georgia Tech"}, {"title": "Authenticated encryption", "course": "gt/ece6612", "code": "ECE 6612", "group": "Foundations", "route": "/courses/gt/ece6612/topics/authenticated-encryption/", "text": "Authenticated encryption with associated data takes a secret key K, nonce N, plaintext P, and associated data A. It protects P while binding the visible context A to that protected message. The diagram shows the authentication tag separately; an algorithm may encode it inside its ciphertext output. Authenticated decryption returns plaintext or failure. The receiver releases plaintext only after successful verification. For a nonce-based mode such as AES-GCM, encryption nonces must be unique for a given key; secrecy of the nonce is unnecessary. Message authentication and replay policy have separate jobs. A previously valid packet can still be a replay, so the surrounding protocol must enforce its sequence or freshness rules. A handshake can bind the symmetric key to an intended peer identity.", "courseTitle": "Computer Network Security", "institution": "Georgia Tech"}, {"title": "TLS identity and session keys", "course": "gt/ece6612", "code": "ECE 6612", "group": "Foundations", "route": "/courses/gt/ece6612/topics/tls-session-keys/", "text": "Ephemeral Diffie–Hellman lets two peers compute a common secret from private contributions and public key shares. In finite-field notation, A = gᵃ mod p and B = gᵇ mod p give Bᵃ = Aᵇ = gᵃᵇ mod p. Modern TLS can instead use an elliptic-curve group. An unauthenticated exchange can establish a secret with an impersonator. In the certificate-authenticated TLS 1.3 flow shown, the client validates the certificate for its intended server identity and verifies the server's CertificateVerify transcript signature. Certificate-path validation and application identity checking have complementary roles. HKDF derives separate traffic keys using the shared secret and protocol context. Finished authenticates the handshake under a derived key, confirming the computed key material and transcript. Certificate authentication, ephemeral key agreement, and encrypted application records therefore remain separate steps.", "courseTitle": "Computer Network Security", "institution": "Georgia Tech"}, {"title": "PHSCS 587 · Physics of Semiconductor Devices", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Course overview", "route": "/courses/byu/phscs587/", "text": "Bands and carrier statistics, transport, junctions and contacts, MOS devices, scaling, and multigate electrostatics.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Bands, states and holes", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/band-states-holes/", "text": "A device needs mobile charge, and its band structure determines which electronic states can carry it. The figure separates the conduction-band edge EC from the valence-band edge EV by the bandgap Eg = EC − EV. These are electron energies, commonly measured in electronvolts (eV). An ideal bulk bandgap contains no allowed extended band states; defects can introduce additional states that need a separate model. Each individual quantum state, including its spin label, can hold at most one electron. A spatial orbital can often accommodate two opposite-spin states. Filling an entire valence band produces no net transport current in equilibrium because the occupied states have balancing velocities. Exciting an electron into the conduction band leaves an unoccupied valence state that can move through successive electron rearrangements. That missing valence electron is described as a hole with positive charge +q, where q = 1.602 × 10⁻¹⁹ C. A conduction electron carries −q. Hole concentration p counts missing valence electrons per volume; conduction-electron concentration n counts electrons in conduction-band states. A hole is a band-dependent excitation, rather than a second positively charged fundamental particle.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Density of states", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/density-of-states-dimensions/", "text": "Confinement changes carrier population even before occupation is considered. The density of states g(E) counts allowed states per energy and per length, area or volume. For a parabolic dispersion with an isolated subband edge E0, g(E) scales as (E − E0)^(d/2 − 1) in dimension d. The figure uses separate normalizations to compare shapes: an ideal 1D edge has an integrable inverse-square-root singularity, a 2D subband adds a step, and a 3D band rises as a square root. For an isotropic 3D parabolic band, g3D(E) = [gs gv/(4π²)](2md/ℏ²)^(3/2)√(E − EC) for E ≥ EC. gs counts spin states, gv counts equivalent valleys, md is the single-valley DOS mass in kg, and ℏ is Planck’s constant divided by 2π. With joule energies this gives states/(J·m³). A 2D subband beginning at Ej instead has g2D(E) = gs gv md/(2πℏ²) above Ej, in states/(J·m²). A valley factor must appear exactly once; an effective mass that already incorporates valleys uses a different convention. Multiply DOS by Fermi occupation and integrate to obtain density: n = ∫ g3D(E)f(E)dE, or sheet density ns = Σj∫ g2D,j(E)f(E)dE. The latter is per area, so it cannot be substituted for a volume density without a spatial distribution or thickness model. To convert SI DOS per joule per m^d to DOS per eV per cm^d, multiply by q/100^d. Finite broadening or finite plotting resolution regularizes an ideal 1D edge.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Effective mass and valleys", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/effective-mass-valleys/", "text": "The periodic crystal changes an electron’s response to a force. For a wave packet in a single band, group velocity is v = (1/ℏ)∇kE and its wave vector obeys ℏ dk/dt = F. Near a parabolic minimum in one direction, E(k) = E0 + ℏ²k²/(2m*), so 1/m* = (1/ℏ²)d²E/dk². The steeper-curvature band in the figure therefore has the smaller effective mass. Real valleys can be ellipsoidal. Principal masses mx, my and mz define E − E0 = (ℏ²/2)(kx²/mx + ky²/my + kz²/mz). The single-valley DOS mass is md = (mx my mz)^(1/3); it summarizes the ellipsoid’s state count. Transport along an applied field instead samples directional masses and scattering. A DOS mass and a conductivity mass therefore need not be equal. Equivalent conduction minima are called valleys. Their multiplicity enters the total DOS, while their orientation affects directional transport. Effective-mass approximations apply over the band region where the chosen expansion is accurate. They require revision for strongly nonparabolic bands, band crossings or low-energy Dirac dispersions.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Quantum wells and subbands", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/quantum-well-subbands/", "text": "When a carrier is confined over a short distance, its wavefunction and boundary conditions determine allowed energies. For an ideal infinite well from x = 0 to L with constant effective mass m*, the one-dimensional eigenstates are ψn(x) = √(2/L)sin(nπx/L) and En = n²π²ℏ²/(2m*L²), with integer n ≥ 1. ψ has units m⁻¹/² so that ∫|ψ|²dx = 1. The figure offsets each wavefunction by its energy level; its oscillation represents amplitude, not a classical particle path. A carrier confined in x but free in the other two directions has a sequence of subband edges En, with continuous in-plane kinetic energy above each edge. Each parabolic 2D subband adds its own DOS step, and FD occupation determines its sheet population. A MOS inversion layer has an electrostatically shaped, finite confinement potential rather than an infinite rectangular well. Its subband energies, spatial charge centroid and self-consistent potential require a more appropriate Schrödinger–Poisson treatment. The ideal well isolates the size and mass scaling that helps interpret those device calculations.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Parabolic and Dirac bands", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/parabolic-dirac-dispersion/", "text": "An effective-mass parabola is one local band model. Near an ordinary parabolic minimum, E − E0 = ℏ²k²/(2m*) and group velocity grows with k. Near an ideal graphene Dirac point, the low-energy branches are approximately E± − ED = ±ℏvF|k|, where ED is the crossing energy and vF is a characteristic velocity. Wave vector k is measured relative to the relevant extremum or crossing. Because velocity is (1/ℏ)∇kE, the ideal linear model has a nearly constant speed magnitude vF on each branch, with direction determined by k and branch. A constant parabolic effective mass obtained from a nonzero second derivative is therefore not the suitable starting model at the crossing. Real bands have limits to the linear approximation. Dimensionality and dispersion together determine DOS. A two-dimensional parabolic band has constant DOS above its edge, whereas an ideal two-dimensional Dirac spectrum has DOS proportional to |E − ED|. A confined nanotube requires its own allowed circumferential wave vectors and subbands; its gap depends on structure. Semimetal band overlap and a zero-gap point crossing are distinct possible band arrangements.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Equilibrium carrier populations", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/carrier-populations/", "text": "Conduction electrons and holes are mobile carriers with charges −q and +q. In an intrinsic semiconductor at thermal equilibrium, their concentrations are equal: n = p = nᵢ. The intrinsic concentration depends strongly on temperature. In the nondegenerate equilibrium model, np = nᵢ². Fully ionized donor doping with ND much larger than nᵢ gives approximately n = ND and p = nᵢ²/ND when acceptor compensation is negligible. Ionized donors supply positive fixed charge that balances the mobile electrons in a neutral bulk region. The Fermi level describes equilibrium occupancy. Moving it closer to the conduction-band edge increases electron population relative to holes. These simple concentration formulas require their stated temperature, ionization, and nondegeneracy assumptions; heavy doping or nonequilibrium needs a fuller model.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Fermi–Dirac occupation", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/fermi-dirac-occupation/", "text": "To predict charge population, first ask whether a state exists and then whether it is occupied. At thermal equilibrium the expected electron occupation of an available state of energy E is f(E) = 1/{1 + exp[(E − EF)/(kBT)]}. EF is the chemical potential, kB is Boltzmann’s constant, and T is absolute temperature in kelvin. E, EF and kBT must use the same energy unit. At finite temperature f(EF) = 1/2, and the transition spans an energy scale of a few kBT. A Fermi level within a bandgap remains a useful chemical potential even though no bulk band state exists at that exact energy. In the zero-temperature limit the distribution becomes a step: allowed states below EF are occupied and those above it are empty. High above EF, where E − EF is several kBT, f(E) approaches exp[−(E − EF)/(kBT)], the Boltzmann tail. This approximation enables familiar exponential carrier formulas. Carrier density still requires a density-of-states integral; a probability by itself has no units of carriers per volume.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Intrinsic density and mass action", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/intrinsic-mass-action/", "text": "A bandgap suppresses thermally excited carriers, while available states and thermal occupation determine how many remain. For nondegenerate equilibrium carriers, n = NC exp[−(EC − EF)/(kBT)] and p = NV exp[−(EF − EV)/(kBT)]. NC and NV are effective densities of states with units of concentration, not dopant concentrations. Multiplying the two formulas eliminates EF: np = NCNV exp[−Eg/(kBT)] = ni². Thus ni = √(NCNV)exp[−Eg/(2kBT)] is the intrinsic concentration, with n = p = ni in a pure equilibrium bulk. For a single isotropic parabolic conduction band, NC = gs gv[md kBT/(2πℏ²)]^(3/2), provided the degeneracy factors have not already been absorbed into md. At fixed material and temperature, increasing equilibrium electron population decreases hole population according to p = ni²/n. Temperature changes both effective DOS and the gap-dependent exponential, so ni must be recomputed. Under injection, separate quasi-Fermi levels can replace the equilibrium mass-action relation; under degeneracy, full Fermi integrals replace the Boltzmann formulas.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Dopants and neutrality", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/dopant-neutrality/", "text": "Chemical doping counts impurity atoms, while electrical neutrality counts charges. Let ND and NA be total donor and acceptor concentrations. ND+ and NA− denote their ionized populations. A neutral homogeneous bulk satisfies n + NA− = p + ND+, since electrons and ionized acceptors contribute negative charge and holes and ionized donors contribute positive charge. Complete ionization is an approximation, often useful for shallow dopants over an appropriate temperature and doping range. Then n − p = ND − NA, and equilibrium nondegenerate mass action supplies np = ni². Both equations are needed to determine n and p. Compensation matters: the net majority population can be far below either chemical dopant concentration. At low temperature some carriers remain bound to dopants, producing freeze-out. Ionized populations then depend on dopant-level occupation, EF and T, and must be solved together with neutrality. At high temperature intrinsic carriers can dominate. Heavy doping may introduce degeneracy, impurity-band effects and bandgap changes, requiring a material-specific model.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Degenerate carrier statistics", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/degenerate-statistics/", "text": "Highly occupied bands require the full Fermi–Dirac distribution. For a nondegenerate conduction band, EC lies sufficiently above EF that f(E) is small throughout the important occupied energies. Once EF approaches or enters the band, exclusion limits each spin state’s occupation to one and the exponential approximation loses accuracy. The reliable general expression is n = ∫EC∞ g(E)/{1 + exp[(E − EF)/(kBT)]} dE. For a parabolic band this can be expressed as a Fermi integral, with its normalization stated explicitly. The figure compares edge occupations rather than integrated carrier densities; it reveals why a Boltzmann prediction above unity cannot describe a state probability. There is no universal dopant concentration at which every material becomes degenerate. The relevant criterion depends on EF relative to the band edge, the DOS, temperature and ionization. Very heavy doping can additionally alter the band structure through disorder and many-body effects. Those changes are distinct from using the correct occupation distribution for a fixed band.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Band energy and potential", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/band-energy-potential/", "text": "Band diagrams track electron energy; voltmeters track differences in electrostatic potential or electrochemical conditions. If material parameters are uniform, a local electrostatic potential ψ shifts an electron’s potential energy by −qψ. Thus EC(x) = EC0 − qψ(x), and EV shifts by the same amount when the bandgap remains fixed. The electric field is Efield = −dψ/dx in one dimension. With EC measured in joules, Efield = (1/q)dEC/dx. A conduction electron experiences force −qEfield, while a hole experiences +qEfield. If energies are plotted numerically in eV, a one-volt potential increase lowers an electron band energy by one eV; keep the unit conversion explicit in derivatives. A flat equilibrium Fermi level can coexist with curved EC and EV. Carrier concentration gradients then accompany the electrostatic field, and drift and diffusion balance to give zero net equilibrium current. Band bending alone does not establish a current without occupancy and boundary conditions.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Poisson and Gauss laws", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/poisson-gauss/", "text": "Electrostatics turns carrier and dopant populations into forces. The semiconductor charge density is ρ = q(p − n + ND+ − NA−), in C/m³ when concentrations are in m⁻³. In a uniform permittivity ε, Gauss’s law gives dEfield/dx = ρ/ε, and Efield = −dψ/dx gives Poisson’s equation d²ψ/dx² = −ρ/ε. The three panels use a positive uniform charge density and the boundary condition Efield(0) = 0. The field therefore rises linearly, and potential curves downward quadratically. Integration constants come from electrode potentials, symmetry or specified fields. Charge density alone determines curvature, rather than a unique absolute potential. At an ideal sheet of free charge σ, the normal displacement jump is D2,n − D1,n = σ, with D = εEfield and σ in C/m². A sheet differs from a volume distribution: it gives a field discontinuity. Boundary conditions at material interfaces and contacts are essential for junction and MOS calculations; consistent length units prevent large permittivity and concentration conversion errors.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Drift, mobility and conductivity", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/drift-mobility/", "text": "An electric field changes carrier momentum between scattering events. In the low-field regime, electron drift velocity is vn = −μnEfield and hole drift velocity is vp = +μpEfield. Positive mobilities μn and μp have units m²/(V·s), or cm²/(V·s) with consistent concentrations and lengths. Thermal motion can be rapid even when its directional average vanishes. Conventional current includes the charge sign: Jn,drift = qnμnEfield and Jp,drift = qpμpEfield. Both drift currents point along the electric field. Total conductivity is σ = q(nμn + pμp), in S/m in SI. In a simple isotropic relaxation-time model, μ = qτm/m*, where τm is a momentum-relaxation time and m* is the transport mass. Lattice vibrations, ionized impurities, interfaces and other processes scatter carriers. Their relative importance changes with temperature, doping and structure, so a single temperature trend for mobility is insufficient. At strong fields, carrier heating and scattering make average drift speed depart from μE and tend toward a material-dependent saturation scale. This microscopic velocity saturation differs from a MOSFET’s channel-electrostatic current saturation, although both can influence its I–V curve.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Diffusion and the Einstein relation", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/diffusion-einstein/", "text": "Random microscopic motion produces a net particle flow from higher to lower concentration. For electrons in one dimension, Fick’s law is Γn = −Dn dn/dx, where Γn is particle flux in m⁻²s⁻¹ and Dn is the diffusion coefficient in m²/s. Multiplying by electron charge gives conventional diffusion current Jn,diff = +qDn dn/dx. The arrows in the figure point in opposite directions because electron charge is negative. For holes, Γp = −Dp dp/dx and Jp,diff = −qDp dp/dx. Including drift gives Jn = qμnnEfield + qDn dn/dx and Jp = qμppEfield − qDp dp/dx. These current densities are in A/m² when SI units are used throughout. A concentration gradient and a field can oppose each other, including the zero-current balance inside an equilibrium junction. For nondegenerate carriers at uniform temperature in the low-field drift–diffusion model, Dn/μn = Dp/μp = kBT/q = VT. VT is the thermal voltage, about 25.9 mV at 300 K. The Einstein relation connects fluctuation-driven spreading to field-driven response. Degeneracy or hot carriers require a generalized relation.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Quasi-Fermi levels", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/quasi-fermi-levels/", "text": "An operating junction can have electrons and holes that each relax internally while remaining out of mutual equilibrium. Their populations can then be described by electron and hole quasi-Fermi levels EFn and EFp. In a nondegenerate local model, n = NC exp[−(EC − EFn)/(kBT)] and p = NV exp[−(EFp − EV)/(kBT)]. All energies use the same reference. Multiplication gives np = ni² exp[(EFn − EFp)/(kBT)]. At equilibrium EFn = EFp = EF and the ordinary mass-action product returns. A positive splitting EFn − EFp corresponds to a carrier product above equilibrium. The splitting is an energy; dividing by q expresses its voltage equivalent. Spatial quasi-Fermi-level gradients describe the electrochemical driving forces for current under the transport assumptions. In an ideal forward-biased junction, the edge populations can be related to an applied voltage through an approximately qV splitting. Contact resistance, recombination and high injection can change this relationship, so the terminal voltage and every local splitting need not coincide.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Continuity and lifetime", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/continuity-lifetime/", "text": "A carrier population changes through transport across its boundary, generation and recombination. Because electron particle flux is Γn = −Jn/q, electron conservation gives ∂n/∂t = (1/q)∇·Jn + G − R. Hole conservation gives ∂p/∂t = −(1/q)∇·Jp + G − R. G and R count created or removed electron–hole pairs per volume per second; current density is conventional electrical current. For a spatially uniform excess minority population in low-level injection, a useful linear approximation is excess net recombination Δn/τn. After an external optical pulse ends, with no carrier flow, dΔn/dt = −Δn/τn and Δn(t) = Δn(0)exp(−t/τn). The lifetime τn is an effective time constant, in seconds, for the specified material, injection regime and mechanisms. With a constant additional uniform generation rate Gext, the same model gives dΔn/dt = Gext − Δn/τn and steady excess Δn = Gextτn. Traps, radiative processes, Auger recombination and surfaces can make the effective lifetime depend on density or position. Boundary extraction and diffusion must be restored when the sample is nonuniform.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Minority-carrier diffusion", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/minority-diffusion/", "text": "A forward-biased junction injects minority carriers into the adjacent quasi-neutral material. Let u measure distance away from the injecting edge into a p-type region, and let Δn(u) = n(u) − np0 be excess minority-electron concentration. With negligible electric field, uniform Dn and low-injection lifetime τn, steady continuity becomes Dn d²Δn/du² − Δn/τn = 0. For a semi-infinite region with Δn(0) fixed by injection and Δn → 0 far away, the solution is Δn(u) = Δn(0)exp(−u/Ln), where Ln = √(Dnτn). Ln has units of length and is the distance over which the excess concentration falls by a factor e in this particular geometry. It compares the time available before recombination with the rate of diffusive spreading. An actual contact at finite distance, a recombining surface, a nonuniform field or high injection changes the boundary-value problem. The exponential profile should therefore be tied to its assumptions. Electron particle flux travels down this profile; its conventional diffusion current has the opposite direction. A junction’s terminal current includes the corresponding hole contribution as well.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "PN depletion electrostatics", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/pn-depletion/", "text": "Joining p-type and n-type material creates concentration gradients. Initial diffusion uncovers negative ionized acceptors on the p side and positive ionized donors on the n side. Their electric field points from n toward p and opposes further majority-carrier diffusion. At equilibrium a common Fermi level and balanced drift and diffusion accompany this built-in field. For an abrupt junction in the depletion approximation, mobile charge is neglected inside widths xp and xn. Charge neutrality per area requires NAxp = NDxn. The total depleted width is W = xp + xn = √{[2εs(Vbi − V)/q](1/NA + 1/ND)}, where εs is semiconductor permittivity, V is positive for forward bias, and Vbi is the equilibrium built-in potential. Width and concentration units must be consistent. For fully ionized nondegenerate uniform sides, Vbi = VT ln(NAND/ni²). Forward bias reduces the depletion potential Vbi − V; reverse bias increases it. The approximation applies while a depleted region exists and effects such as high injection, tunneling, breakdown and strong grading can be neglected. The less heavily doped side occupies more of W.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "PN diode injection", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/pn-diode-injection/", "text": "A PN diode conducts by changing the carrier populations at the edges of its depletion region. Under ideal nondegenerate low-level injection, forward voltage V raises each minority edge concentration by exp(V/VT), with VT = kBT/q. Low-level injection means the excess minority density remains small compared with the equilibrium majority density, so the majority population changes little. Carriers then diffuse into the quasi-neutral regions and recombine or reach a contact. For long uniform quasi-neutral regions and negligible depletion-region recombination, the ideal result is I = Is[exp(V/VT) − 1]. The saturation scale is Is = qA ni²[Dn/(LnNA) + Dp/(LpND)], where A is junction area, Dn and Dp are minority diffusion coefficients, and Ln and Lp are diffusion lengths. Both carrier contributions add to the terminal current. SI concentrations, lengths and diffusivities make Is an ampere. The exponential law describes a model with specified boundaries and transport. In high injection, excess carrier density becomes comparable to or exceeds the original majority density, so both populations change substantially. Depletion-region recombination, series resistance, leakage and breakdown also alter the response. Forward current stores excess minority charge; changing that charge during switching links the static law to lifetime and transient continuity.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Junction tunneling", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/junction-tunneling/", "text": "A heavily doped reverse-biased junction can develop a large electric field over a short distance. Band bending can then place occupied valence states on one side at energies matching empty conduction states on the other. An electron can tunnel between these states through the forbidden region, creating a conduction electron and a valence hole. The probability depends on the barrier shape, bandgap, carrier masses and allowed transitions. A semiclassical one-dimensional guide is transmission proportional to exp[−2∫κ(x)dx], where κ is an inverse decay length in the classically forbidden region. Narrowing that region can strongly increase tunneling. The figure is an energy-versus-position schematic, rather than a literal particle trajectory. Band-to-band tunneling and impact-ionization avalanche are distinct reverse-current mechanisms. Avalanche involves energetic carriers generating additional pairs through collisions; tunneling accesses states quantum mechanically across a barrier. Which mechanism dominates depends on field, doping, band structure and temperature. The ordinary ideal Shockley law excludes both breakdown mechanisms.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Bipolar injection and storage", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/bipolar-carrier-storage/", "text": "The same minority-carrier physics appears in a bipolar transistor. In forward-active operation of an NPN device, the emitter–base junction is forward biased and the base–collector junction is reverse biased. Electrons injected from the n-type emitter become minority carriers in the p-type base. A sufficiently thin base allows many to diffuse to the collector depletion region, whose field sweeps them onward. Some injected electrons recombine in the base, and hole injection into the emitter also contributes to base-current requirements. Using positive terminal-current magnitudes in the usual forward-active convention, IE = IC + IB. Define common-base gain α = IC/IE and common-emitter gain β = IC/IB; then β = α/(1 − α). These ratios summarize terminal behavior rather than replacing the transport and recombination model. Injected minority charge is stored in the device. Switching conditions must change that charge as well as terminal voltage, so lifetime, diffusion distance and junction bias history affect speed. Deep saturation forward biases both junctions and can add stored charge. This gives context for comparing a majority-carrier Schottky contact with a minority-injecting PN structure under specified operating conditions.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Work functions and affinity", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/workfunction-affinity/", "text": "Before joining materials, a common vacuum reference helps organize their electron energies. Write qΦm = Evac − EFm for the metal work-function energy and qΦs = Evac − EFs for the semiconductor work-function energy. Electron affinity is qχ = Evac − EC. Here Φ and χ are expressed as volt-equivalent quantities and q times them is energy; the same numerical values are often quoted in eV for an electron. For an ideal clean metal–n-semiconductor interface without an additional interface dipole, the Schottky–Mott electron barrier is φBn = Φm − χ. The semiconductor work function additionally depends on EF relative to EC, so doping can change Φs without changing electron affinity in the simple rigid-band model. Real interfaces can depart strongly from this ideal barrier prediction. The same bookkeeping enters MOS flat-band voltage. In an ideal charge-free oxide, VFB = Φg − Φs using consistent voltage units. A fixed oxide sheet charge Qox′ adds a term −Qox′/Cox′ in the elementary model. Zero applied bias establishes equilibrium, but flat semiconductor bands occur at Vg = VFB and therefore can require a nonzero gate voltage.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Schottky and ohmic contacts", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/schottky-ohmic/", "text": "Every device needs contacts, and a metal–semiconductor interface can either limit transport or serve as a nearly transparent connection. A Schottky barrier presents an energy barrier to a majority-carrier population. Its rectifying behavior depends on the barrier height, depletion width, applied bias and transport mechanism. Band bending is therefore part of the contact problem, even when the bulk semiconductor is neutral. An ohmic contact has a sufficiently low, approximately linear voltage–current relation over its intended operating range. One route is a small effective majority-carrier barrier. Another is heavy contact-region doping that narrows the barrier enough for substantial tunneling. The contact can then be conductive even though a barrier remains in the band diagram. The differential specific contact resistivity can be written ρc = dV/dJ near a stated bias, with units Ω·m². Actual contact resistance also depends on area and current spreading. Interface states, interfacial layers, processing and polarity matter. A generic metal choice or a work-function sketch alone does not establish a reliably ohmic fabricated contact.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Interface states and pinning", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/interface-pinning/", "text": "An ideal work-function calculation can fail when the interface contains electronic states and dipoles. Defects, bonding changes and metal-induced gap states can exchange charge with the adjoining materials. This redistribution shifts the electrostatic potential across the interface and changes the relationship between metal work function and semiconductor barrier height. A useful empirical sensitivity is S = dφBn/dΦm, with barrier and work-function quantities expressed in the same voltage units. The ideal Schottky–Mott limit has S near one. Strong Fermi-level pinning gives a much smaller sensitivity: changing the metal has a weaker effect on the barrier. The figure compares slopes rather than assigning a universal pinned energy. Pinning strength depends on the actual material pair, surface preparation, interfacial layers and processing. An interface-state density is commonly quoted per area per energy, such as cm⁻²eV⁻¹; its electrostatic effect also depends on occupation. Depinning strategies therefore require an interface model and measurement, rather than a work-function change alone.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Transport over and through barriers", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/barrier-transport/", "text": "A contact barrier filters carrier energies. Thermionic emission uses carriers with sufficient thermal energy to pass over its top. In a simple ideal Schottky model, the thermionic current scale has a strong factor exp[−qφB/(kBT)], with barrier voltage φB and temperature T. The prefactor depends on the band structure and emission model. Field emission tunnels through a sufficiently thin barrier from energies close to the occupied carrier supply. Thermionic-field emission combines thermal access to elevated energies with tunneling through the remaining barrier. The three arrows separate energy routes; they do not represent classical motion through a forbidden region. Doping, electric field and temperature help select the dominant route. A depletion width can shrink with increasing doping or bias, making tunneling important even when a barrier height remains. Conversely, a wide barrier can suppress tunneling so that thermal activation dominates. Interpreting a measured I–V curve therefore benefits from temperature dependence, doping information and a consistent barrier profile, rather than fitting every contact to one exponential law.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Image-force barrier lowering", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/image-force-lowering/", "text": "A carrier near an ideal conducting plane polarizes the conductor. In the classical planar model, an electron at distance x in a dielectric of permittivity ε has image interaction energy Uim(x) = −q²/(16πεx). The factor includes the work of building the induced charge distribution. It is an attractive energy correction, measured in joules in SI. For a positive field magnitude F that lowers the outward barrier, model its energy as U(x) = qφB − qFx − q²/(16πεx). The maximum occurs at xm = √[q/(16πεF)]. Its reduction relative to the unrounded interface barrier is ΔU = qΔφ, where Δφ = √[qF/(4πε)] in volts. Increasing F by four therefore doubles the classical barrier-lowering voltage. This model assumes an ideal planar metal, a locally uniform field and a continuum dielectric response. Its divergence as x approaches zero signals the failure of that continuum description at atomic distances. Nonplanar contacts, two-dimensional screening and interface chemistry require more detailed models. Image-force lowering is one correction to contact transport, rather than a replacement for the full barrier profile.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "MOS gate electrostatics", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/mos-gate-electrostatics/", "text": "A MOS structure places an insulating oxide between a gate and semiconductor. For a p-type body, increasing positive gate bias first repels holes and exposes negative ionized acceptors. Sufficient surface band bending attracts an electron inversion layer. The oxide capacitance per unit area is C′ox = εox/tox. With surface potential ψs measured relative to the bulk, the ideal voltage split is Vg − VFB = ψs + Vox. Gate sheet charge is Q′g = C′oxVox, in C/m², and balances the semiconductor sheet charge when additional oxide charges are absent. Oxide capacitance and measured MOS capacitance are different quantities. In depletion, semiconductor charge changes contribute an additional series capacitance. Inversion response also depends on measurement frequency and carrier supply. Specify regime and frequency before interpreting a C–V curve.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "MOS C–V and response time", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/mos-capacitance-frequency/", "text": "A capacitance measurement asks how much gate charge changes for a small voltage change around a DC bias. Per unit area, C′ = dQg′/dVg and Cox′ = εox/tox. In an ideal MOS capacitor with a conductive gate, oxide and semiconductor differential capacitances are in series: 1/C′ = 1/Cox′ + 1/Cs′. Cs′ represents the semiconductor charge response, including whichever mobile and depletion components can follow the measurement. For a p-type body, accumulation commonly gives C′ near Cox′. Depletion widens a space-charge region and lowers C′. In strong inversion with a sufficiently slow small signal and an available minority-carrier supply, inversion charge follows and capacitance rises toward Cox′. At high small-signal frequency the minority population cannot change appreciably, so the measured capacitance stays near the series combination with the maximum-depletion capacitance Cdep,max′ = εs/Wmax. The DC sweep rate is a second timescale. A rapid move into inversion can leave too few minority carriers to establish the equilibrium inversion layer, extending depletion beyond Wmax and reducing capacitance below its high-frequency equilibrium minimum: deep depletion. Interface traps, series resistance and contact geometry add further responses. Always state bias history, AC frequency and how minority carriers are supplied when interpreting C–V.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Polysilicon gate depletion", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/polysilicon-gate-depletion/", "text": "Treating the gate as an ideal conductor assumes that its internal potential drop is negligible. A doped polysilicon gate can instead develop a depleted region near the oxide under an appropriate bias. That region contains exposed ionized dopants and supports an electric field, adding voltage drop before the field reaches the oxide and semiconductor. In a simple depletion approximation, the gate-region capacitance per area is Cpoly′ = εSi/Wpoly. Its series contribution gives 1/Ctotal′ = 1/Cpoly′ + 1/Cox′ + 1/Cs′. Wpoly is a bias-dependent gate depletion width in metres, and each C′ is in F/m². A smaller Cpoly′ lowers the incremental gate charge produced by a voltage change and weakens electrostatic control. Gate depletion differs from depletion in the semiconductor body and from the finite centroid of quantum-confined inversion charge. All can introduce voltage drops, but they arise in different regions and require different models. A sufficiently conductive metal gate removes the particular finite-doped-polysilicon depletion term, while work-function and interface effects still remain.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Self-aligned fabrication", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/self-aligned-fabrication/", "text": "A transistor’s electrical dimensions depend on how successive fabrication patterns line up. In a conceptual self-aligned gate-first process, a patterned gate shields the channel region while exposed regions receive source/drain implantation. The gate edge supplies the alignment reference, reducing the need to align an independent source/drain mask precisely to that edge. Sidewall spacers establish an additional geometric offset for later processing. Isolation, gate dielectric formation, patterning, doping, activation and contacts all contribute to the resulting cross section. Implant straggle and subsequent thermal diffusion mean that an electrical junction edge is a concentration profile rather than an infinitely sharp mask edge. Material purity, interface quality and repeatable processing are part of device behavior: they affect traps, mobility, leakage, contact resistance and variability. The diagram conveys the alignment principle. Specific modern technologies can use different gate ordering, replacement-gate steps and three-dimensional geometries, so a complete process flow must match the intended technology.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "MOSFET terminal capacitance", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/mos-terminal-capacitance/", "text": "A MOSFET is a multi-terminal device. Its small-signal capacitances come from derivatives of terminal charge with respect to terminal voltage under a stated sign convention and fixed remaining biases. A single oxide capacitance does not describe every terminal response. For an ideal long-channel transistor in strong inversion at very low VDS, symmetry gives intrinsic Cgs ≈ Cgd ≈ CₒₓWL/2. In saturation, the channel charge model gives Cgs ≈ 2CₒₓWL/3 and intrinsic Cgd ≈ 0. The gate-to-body channel contribution is small in these strong-inversion limits. These are limiting quasi-static results, not a complete high-frequency capacitance matrix. Source/drain overlap, fringing, junction capacitance and non-quasi-static transport add further terms. A near-zero intrinsic Cgd does not mean an actual device has zero drain-to-gate coupling.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "MOS body effect", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/mos-body-effect/", "text": "For an nMOS in a p-type body, define VSB = VS − VB. Increasing a nonnegative VSB reverse biases the source–body junction, enlarges depletion charge and requires a larger gate voltage to establish inversion. A uniform-doping approximation is Vth = Vth0 + γ[√(2φF + VSB) − √(2φF)], with γ = √(2qεsiNA)/Cₒₓ. Here φF = UT ln(NA/nᵢ) is positive for the chosen p-body convention, Cₒₓ is per area, and γ has units √V. Signs matter. A formula written with VBS instead uses VBS = −VSB. The expression assumes depletion electrostatics, adequate ionization and reverse bias. It should not be extrapolated into forward-junction conduction.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Long-channel MOSFET current", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/mos-regional-current/", "text": "A positive nMOS gate overdrive Vov = VGS − Vth creates mobile inversion charge. Drain voltage drives that charge along the channel. Here β = μeff Cₒₓ W/L has units A/V², and Cₒₓ is oxide capacitance per gate area. In the long-channel regional approximation, ID = β[Vov VDS − m VDS²/2] until VDS,sat = Vov/m. The saturation branch is ID,sat = βVov²/(2m). The depletion coupling factor m ≈ 1 + Cdep/Cₒₓ is dimensionless. Setting m = 1 gives the familiar square-law model used in the adjustable figure. These equations assume strong inversion, gradual channel variation, constant effective mobility and negligible series resistance. Do not continue the parabola beyond its maximum: its falling branch is outside the approximation. Current continues through the high-field drain region after saturation. A pMOS has reversed voltage and current polarities.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Subthreshold swing", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/subthreshold-swing/", "text": "Weak inversion contains mobile carriers even below threshold. In a long-channel thermionic model, diffusion dominates and ID is proportional to exp[(VGS − Vth)/(mUT)] × [1 − exp(−VDS/UT)], where UT = kT/q is thermal voltage. Subthreshold swing S = dVGS/dlog₁₀ID = ln(10)mUT is measured in volts per current decade. Smaller S means fewer gate volts are needed for a tenfold current change. At 300 K, the positive-capacitance thermionic ideal m = 1 gives about 59.5 mV/decade. Depletion coupling makes m greater than one. Short-channel electrostatics, traps and nonideal transport can further alter the measured swing. The familiar room-temperature limit belongs to this stated mechanism and is not a universal bound on every proposed switch.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Channel-length modulation", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/channel-length-modulation/", "text": "In a real device, a stronger drain field changes the drain-side high-field region and the effective conducting channel. A current labeled saturated can therefore have a finite output slope. This effect is distinct from carrier velocity saturation. A simple local fit is ID ≈ ID,sat[1 + λCLM(VDS − VDS,sat)] for VDS ≥ VDS,sat. The coefficient λCLM has units V⁻¹. Subtracting the saturation voltage makes the correction equal one at the regional boundary, so the joined current is continuous. This piecewise model has a slope change at the join. It is a teaching approximation, not a smooth compact model or a first-principles extraction of effective channel length. DIBL, mobility change and series resistance may also affect a measured output characteristic.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "MOS channel mobility", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/mos-channel-mobility/", "text": "Effective channel mobility is a carrier-weighted average: μeff = ∫μ(x)n(x)dx / ∫n(x)dx across the inversion layer. It converts a nonuniform carrier distribution and local response into a useful transport parameter. Phonons, charged impurities and interface roughness compete. A stronger normal field pulls inversion charge toward the interface, often increasing roughness scattering. For the empirical electron model, Eeff = (|Qd| + |Qi|/2)/εsi; the corresponding hole data use a one-third inversion-charge weighting. These weightings describe particular empirical mobility relationships. The reading reports approximate high-temperature phonon-limited μeff ∝ T⁻³ᐟ². That is not a universal curve across all fields and temperatures. A Matthiessen model, 1/μeff ≈ Σᵢ1/μᵢ, is a useful independent-scattering approximation, rather than an exact rule for every channel.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Strain engineering", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/strain-engineering/", "text": "Strain changes the crystal lattice and therefore its electronic bands. It may lift valley degeneracy, change band curvature and alter inter-valley scattering. Carrier populations can move toward bands that conduct more effectively along a chosen direction. Near a parabolic band edge, the inverse conductivity effective mass is related to band curvature by 1/m* = (1/ℏ²)d²E/dk² along the transport direction. Effective mass is directional; it is not the electron’s free-space rest mass. Tensile and compressive, uniaxial and biaxial stress have different effects on electrons and holes. A useful engineering statement identifies the material, crystal orientation, stress direction and carrier type. It does not assume any strain improves every device.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Temperature and threshold", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/threshold-temperature/", "text": "Thermal voltage UT = kT/q increases with temperature. Intrinsic carrier concentration nᵢ(T) changes strongly as well. The body potential φF = UT ln[NA/nᵢ(T)] therefore cannot be evaluated by changing UT while holding every other temperature-dependent term fixed. A local compact approximation is Vth(T) ≈ Vth(T₀) + αT(T − T₀), where αT has units V/K. Silicon MOS thresholds often fall with temperature over an ordinary operating range, but the coefficient depends on doping, flat-band voltage and the threshold definition. Current does not follow threshold alone. Mobility, leakage, series resistance and the chosen operating region also change with temperature. A lower threshold and lower mobility can push current in opposite directions.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Inversion-layer quantization", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/threshold-quantization/", "text": "Carriers confined near the oxide interface do not have arbitrary energy for motion normal to the surface. A quantum calculation gives subband energies and wavefunctions, changing both population and the depth at which inversion charge sits. In the nMOS model discussed here, raising the lowest allowed carrier energies reduces inversion charge at a given classical surface potential. Additional surface potential Δψs is needed to reach the selected inversion condition. A local gate conversion gives ΔVth ≈ mΔψs. This correction is distinct from depletion inside a polysilicon gate. A narrow-body device may also have confinement from its finite silicon thickness. The often-used 1/t² energy scaling belongs to an ideal infinite well; actual oxide barriers, effective masses and electrostatics require a self-consistent model.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Threshold, on-current and leakage", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/threshold-ion-ioff/", "text": "Threshold is both an electrostatic concept and a parameter extracted by a stated measurement rule. Different extraction methods can produce different numerical thresholds. Always report the biases and criterion used. Lower threshold generally increases gate overdrive at a fixed supply, but also raises off-current. In weak inversion, a threshold reduction equal to one subthreshold swing raises modeled off-current tenfold. At the circuit level, a simple leakage estimate is Pstandby = NVDDIoff for N equally leaking off devices under the chosen state assumptions. The ratio Ion/Ioff alone is not a complete device score: a threshold shift can change the ratio without providing the required drive at a permitted leakage level. Compare Ion at a specified Ioff, supply, geometry, load and temperature, or state the full design tradeoff.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Channel doping profiles", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/channel-profile-engineering/", "text": "Uniform doping is convenient, but practical channel profiles may place dopants preferentially near the surface or deeper in the body. Profile engineering balances threshold, depletion control, mobility, junction behavior and statistical variability. For a one-dimensional depleted p-body with x measured from the surface and zero field at x = Wd, charge magnitude is |Qd| = q∫₀ᵂᵈNA(x)dx. The surface-to-bulk potential magnitude is ψs = (q/εsi)∫₀ᵂᵈxNA(x)dx. Thus the charge depends on total dose while potential also depends on its depth moment. At fixed boundary potential, Wd is part of the solution; the displayed equal-width comparison is not a claim that two profiles have identical depletion widths under identical bias. Higher doping can strengthen electrostatic control while degrading mobility or increasing variability.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Short-channel effects and DIBL", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/short-channel-effects/", "text": "A long channel has an interior region controlled mainly by the gate. As channel length shrinks, source and drain boundary conditions influence more of that region. The potential is then inherently two-dimensional. Threshold rolloff describes a decrease in extracted threshold as channel length decreases at specified biases. Drain-induced barrier lowering, DIBL, describes the drain-bias-dependent lowering of the source injection barrier at fixed channel length. The two effects share electrostatic origins but are measured by different changes. A common positive DIBL metric is −ΔVth/ΔVDS, stated with the threshold extraction method. Short-channel degradation can also worsen subthreshold swing. A simple barrier sketch alone does not predict a quantitative threshold or current.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Poisson equations and scale length", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/poisson-scale-length/", "text": "In a depleted region with prescribed fixed charge, Poisson’s equation is linear. One can split the potential into a particular solution for that charge and homogeneous solutions that enforce source, drain and gate boundary conditions. This superposition does not apply unchanged to arbitrary nonlinear carrier populations. Separation of variables gives electrostatic eigenmodes. In the reading’s convention, the leading contribution to the minimum channel potential contains exp[−πL/(2λ₁)]. Larger L/λ₁ suppresses contact influence. Both the exponent convention and the omitted voltage-dependent prefactor matter. If a decay length ℓ is defined by a spatial factor exp(−y/ℓ), it corresponds to λ₁/π for the stated mode, not λ₁ itself. A symmetric double-gate approximation ℓ ≈ √[εsi tsi tox/(2εox)] is a limited thin-angle model; exact dielectric boundary matching retains geometric floors and must be used before extrapolating to extreme high-κ oxides.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Constant-field scaling", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/constant-field-scaling/", "text": "For a scale factor κ > 1, ideal constant-field scaling divides device dimensions and voltages by κ while multiplying doping by κ. With unchanged permittivity and mobility, electric field and carrier velocity remain unchanged. Gate capacitance C scales as area/thickness, hence 1/κ. Current scales as 1/κ, and delay CV/I as 1/κ. Switching energy proportional to CV² scales as 1/κ³. At proportionally faster operation, per-device dynamic power scales as 1/κ² while ideal device density rises as κ², leaving power per area unchanged. These are linked ideal assumptions, not a promise from shrinking lithography alone. Thermal voltage, bandgap and built-in potentials do not follow geometric scaling. Leakage, oxide tunneling, contact resistance and finite doping constrain the extrapolation.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "CMOS inverter and noise margins", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/cmos-inverter/", "text": "A CMOS inverter connects a pMOS pull-up and nMOS pull-down to a shared output. At a low input the pMOS conducts and the nMOS is off, driving the output high. A high input reverses those roles. During a transition, both can conduct. The voltage transfer curve Vout(Vin) determines logic restoration. The trip point VM satisfies Vout = Vin; it differs from the usual VIL and VIH points defined by slope dVout/dVin = −1. Static noise margins are NML = VIL − VOL and NMH = VOH − VIH. Matched switching does not usually mean equal transistor widths because electron and hole drive differ. Ideal zero static rail current assumes no leakage. Real standby current, dynamic charging and brief overlap conduction all contribute to power.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Double-gate electrostatics", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/double-gate-electrostatics/", "text": "A thin double-gate device places gate control on opposite sides of the silicon. This can reduce source/drain penetration, allow lower channel doping and make the full body participate in weak-inversion conduction. The exact charge distribution changes with bias. For the reading’s symmetric dielectric-matched model, eigenlengths satisfy tan(πtox/λ)tan[πtsi/(2λ)] = εox/εsi. The associated longitudinal mode contains sinh(πy/λ). Physical oxide and body thickness matter; increasing dielectric constant does not eliminate all geometric length limits. More gate-controlled channel can increase both current and intrinsic gate charge. In a thought experiment with two identical independent channels, doubling current also doubles intrinsic capacitance, so CV/I does not automatically improve. Actual advantages require comparing electrostatics, geometry, capacitance and drive together.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Nanowire and gate-all-around electrostatics", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/nanowire-electrostatics/", "text": "A gate surrounding a thin wire controls its potential from all azimuthal directions. Low mobile charge can occupy much of the body; at stronger inversion the distribution can move toward the perimeter. Better geometric control does not remove confinement or tunneling limits. For ideal concentric cylinders, oxide capacitance per channel length is Cₒₓ,L = 2πεox / ln[(R + tox)/R], with units F/m. This differs from planar oxide capacitance per area, εox/tox in F/m². Charge and current equations must use matching dimensional quantities. Using electron inversion charge per length Qinv,L < 0, the long-channel drift expression is ID = −μeff Qinv,L dV/dy under a consistent current convention. A realistic nanoscale calculation may require quantum populations, contact effects and transport beyond constant-mobility drift.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Ballistic injection and backscattering", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/ballistic-injection/", "text": "A short channel is not automatically described by the long-channel mobility law. Injection from contacts and scattering that returns carriers toward the source can determine the net current. Ballistic means negligible scattering through the relevant transport region, not infinite speed. In a simple two-population picture, set the incident population to one and reflected population to r, with speed magnitudes vT in opposite directions. Net flux is proportional to vT(1 − r), total population to 1 + r, and vnet = vT(1 − r)/(1 + r). At r = 0 the net velocity equals the injection-speed scale. The formula assumes a particular distribution and equal speed magnitudes; real contacts and energy-dependent transmission require a fuller transport model. In the ballistic limit, increasing a bulk mobility parameter is not the same as improving injection.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Reading a technical figure", "course": "byu/phscs587", "code": "PHSCS 587", "group": "Foundations", "route": "/courses/byu/phscs587/topics/technical-reading/", "text": "Start with the physical question the material answers. Identify what the figure represents, where its boundaries are, which direction each axis increases and what each line or region means. Translate one visible feature into a sentence before reaching for an equation: for example, a concentration gradient points downhill toward the particle flux. For each equation, name every symbol, its unit, its location in the figure and whether it is an input, a derived quantity or a boundary condition. Record the assumptions that make the relation valid. Check dimensions and a limiting case, such as zero field, zero excess generation, a very wide well or a fully ionized bulk. These checks connect the mathematical expression to a physical prediction. Then explain the same idea to an imagined learner using the figure as the reference. Pose a small change to one input and predict its consequence before calculating. If the prediction is unclear, turn that gap into a specific question to resolve from the source. Active reconstruction and a fresh example provide stronger evidence of understanding than recognition while rereading.", "courseTitle": "Physics of Semiconductor Devices", "institution": "Brigham Young University"}, {"title": "Progress and preferences", "course": "shared", "code": "Course Lab", "courseTitle": "", "institution": "", "group": "Saved work", "route": "/progress/", "text": "Export import and move saved settings and written practice between hostnames"}];
